// Trazabilidad de tareas — reads docs/data.json (generated by scripts/build_dashboard.py from
// PROGRESS.md) and renders stat tiles, filters, and a filterable task grid. No build step: this
// file is plain, dependency-free JS served as-is by GitHub Pages.

const REPO_BLOB_BASE = "https://github.com/Deivs117/paper-revision/blob/main/";

const STATUS_LABEL = {
  "pending": "Pendiente",
  "drafted": "Borrador",
  "applied": "Aplicado",
  "synced-to-overleaf": "Sincronizado a Overleaf",
};

const state = {
  tasks: [],
  filters: { category: new Set(), status: new Set(), owner: new Set(), reviewer: new Set() },
  search: "",
};

function el(tag, className, text) {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

function uniqueSorted(values) {
  return Array.from(new Set(values)).sort((a, b) => a.localeCompare(b, "es"));
}

async function loadData() {
  const res = await fetch("data.json", { cache: "no-store" });
  if (!res.ok) throw new Error(`No se pudo cargar data.json (${res.status})`);
  return res.json();
}

function renderMeta(payload) {
  const meta = document.getElementById("meta");
  const generated = new Date(payload.generatedAt).toLocaleString("es-CO", { dateStyle: "medium", timeStyle: "short" });
  const committed = payload.progressLastCommit
    ? new Date(payload.progressLastCommit).toLocaleString("es-CO", { dateStyle: "medium", timeStyle: "short" })
    : "—";
  meta.innerHTML = "";
  meta.appendChild(el("div", null, `Panel generado: ${generated}`));
  meta.appendChild(el("div", null, `Último cambio en PROGRESS.md: ${committed}`));
  const link = el("a", null, "PROGRESS.md ↗");
  link.href = REPO_BLOB_BASE + "PROGRESS.md";
  link.target = "_blank";
  link.rel = "noopener";
  meta.appendChild(link);
}

function renderStats(tasks) {
  const stats = document.getElementById("stats");
  stats.innerHTML = "";

  const total = tasks.length;
  const synced = tasks.filter((t) => t.status === "synced-to-overleaf").length;
  const drafted = tasks.filter((t) => t.status === "drafted").length;
  const applied = tasks.filter((t) => t.status === "applied").length;
  const pending = tasks.filter((t) => t.status === "pending").length;

  const tiles = [
    { label: "Total de tareas", value: total, accent: "accent-total" },
    { label: "Sincronizadas a Overleaf", value: synced, accent: "accent-synced" },
    { label: "Borrador", value: drafted, accent: "accent-drafted" },
    { label: "Aplicado (sin sincronizar)", value: applied, accent: "accent-applied" },
    { label: "Pendientes", value: pending, accent: "accent-pending" },
  ];

  for (const tile of tiles) {
    const node = el("div", `stat-tile ${tile.accent}`);
    node.appendChild(el("div", "value", String(tile.value)));
    node.appendChild(el("div", "label", tile.label));
    stats.appendChild(node);
  }

  const progressTile = el("div", "progress-tile");
  const head = el("div", "progress-head");
  head.appendChild(el("span", null, "Avance general"));
  const pct = total ? Math.round((synced / total) * 100) : 0;
  head.appendChild(el("span", null, `${pct}% sincronizado`));
  progressTile.appendChild(head);

  const track = el("div", "progress-track");
  const segments = [
    { cls: "synced", count: synced },
    { cls: "applied", count: applied },
    { cls: "drafted", count: drafted },
    { cls: "pending", count: pending },
  ];
  for (const seg of segments) {
    if (!seg.count) continue;
    const bar = el("div", `progress-seg ${seg.cls}`);
    bar.style.width = `${(seg.count / total) * 100}%`;
    track.appendChild(bar);
  }
  progressTile.appendChild(track);
  stats.appendChild(progressTile);
}

function makePill(container, { value, dataAttr, label, active }, onToggle) {
  const pill = el("button", "pill", label);
  pill.type = "button";
  pill.dataset[dataAttr] = value;
  if (active) pill.classList.add("active");
  pill.addEventListener("click", () => onToggle(value));
  container.appendChild(pill);
}

function renderFilters(tasks) {
  const categories = uniqueSorted(tasks.map((t) => t.category));
  const statuses = uniqueSorted(tasks.map((t) => t.status));
  const owners = uniqueSorted(tasks.flatMap((t) => t.owner));
  const reviewers = uniqueSorted(tasks.map((t) => t.reviewer).filter((r) => r && r !== "—"));

  const groups = [
    { id: "filter-category", key: "category", values: categories, dataAttr: "cat", labelFn: (v) => v },
    { id: "filter-status", key: "status", values: statuses, dataAttr: "status", labelFn: (v) => STATUS_LABEL[v] || v },
    { id: "filter-owner", key: "owner", values: owners, dataAttr: "owner", labelFn: (v) => v },
    { id: "filter-reviewer", key: "reviewer", values: reviewers, dataAttr: "reviewer", labelFn: (v) => `R${v}` },
  ];

  for (const group of groups) {
    const container = document.getElementById(group.id);
    container.innerHTML = "";
    for (const value of group.values) {
      makePill(
        container,
        { value, dataAttr: group.dataAttr, label: group.labelFn(value), active: state.filters[group.key].has(value) },
        (v) => toggleFilter(group.key, v),
      );
    }
  }
}

function toggleFilter(key, value) {
  const set = state.filters[key];
  if (set.has(value)) set.delete(value); else set.add(value);
  renderFilters(state.tasks);
  renderTasks();
}

function taskMatches(task) {
  const f = state.filters;
  if (f.category.size && !f.category.has(task.category)) return false;
  if (f.status.size && !f.status.has(task.status)) return false;
  if (f.owner.size && !task.owner.some((o) => f.owner.has(o))) return false;
  if (f.reviewer.size && !f.reviewer.has(task.reviewer)) return false;
  if (state.search) {
    const q = state.search.toLowerCase();
    const haystack = `${task.id} ${task.requirement}`.toLowerCase();
    if (!haystack.includes(q)) return false;
  }
  return true;
}

function patchLink(patchFile) {
  if (!patchFile || patchFile === "—" || patchFile.includes("*")) return null;
  return REPO_BLOB_BASE + patchFile;
}

function renderTaskCard(task) {
  const card = el("div", "task-card");
  card.dataset.category = task.category;

  const top = el("div", "card-top");
  top.appendChild(el("span", "task-id", task.id));
  const badgeGroup = el("span", "badge-group");
  const statusBadge = el("span", `badge status-${task.status}`);
  statusBadge.appendChild(el("span", "dot"));
  statusBadge.appendChild(document.createTextNode(STATUS_LABEL[task.status] || task.status));
  badgeGroup.appendChild(statusBadge);
  if (task.activity) {
    const activityBadge = el("span", "badge activity");
    activityBadge.title = task.activity;
    activityBadge.appendChild(el("span", "dot"));
    activityBadge.appendChild(document.createTextNode("En desarrollo"));
    badgeGroup.appendChild(activityBadge);
  }
  top.appendChild(badgeGroup);
  card.appendChild(top);
  if (task.activity) {
    card.appendChild(el("div", "task-activity-note", task.activity));
  }

  card.appendChild(el("div", "task-requirement", task.requirement));

  const metaRow = el("div", "task-meta-row");
  metaRow.appendChild(el("span", `tag category-${task.category}`, task.category));
  if (task.reviewer && task.reviewer !== "—") {
    metaRow.appendChild(el("span", "tag", `Revisor ${task.reviewer}`));
  } else {
    metaRow.appendChild(el("span", "tag", "Corrección interna"));
  }
  card.appendChild(metaRow);

  const ownerList = el("div", "owner-list");
  for (const owner of task.owner) {
    ownerList.appendChild(el("span", "owner-chip", owner));
  }
  card.appendChild(ownerList);

  const footer = el("div", "task-footer");
  footer.appendChild(el("span", null, task.dataSource && task.dataSource !== "—" ? "Requiere datos nuevos" : "Solo redacción"));
  const link = patchLink(task.patchFile);
  if (link) {
    const a = el("a", null, "Ver patch ↗");
    a.href = link;
    a.target = "_blank";
    a.rel = "noopener";
    footer.appendChild(a);
  } else if (task.patchFile && task.patchFile !== "—") {
    footer.appendChild(el("span", null, task.patchFile));
  }
  card.appendChild(footer);

  return card;
}

function renderTasks() {
  const grid = document.getElementById("task-grid");
  const emptyState = document.getElementById("empty-state");
  const resultCount = document.getElementById("result-count");

  const visible = state.tasks.filter(taskMatches);
  resultCount.textContent = `${visible.length} de ${state.tasks.length} tareas`;

  grid.innerHTML = "";
  if (!visible.length) {
    emptyState.style.display = "block";
    return;
  }
  emptyState.style.display = "none";
  for (const task of visible) {
    grid.appendChild(renderTaskCard(task));
  }
}

function wireControls() {
  document.getElementById("search").addEventListener("input", (e) => {
    state.search = e.target.value.trim();
    renderTasks();
  });
  document.getElementById("clear-filters").addEventListener("click", () => {
    for (const key of Object.keys(state.filters)) state.filters[key].clear();
    state.search = "";
    document.getElementById("search").value = "";
    renderFilters(state.tasks);
    renderTasks();
  });
}

async function init() {
  try {
    const payload = await loadData();
    state.tasks = payload.tasks;
    renderMeta(payload);
    renderStats(state.tasks);
    renderFilters(state.tasks);
    renderTasks();
    wireControls();
  } catch (err) {
    document.getElementById("task-grid").innerHTML = "";
    const errorBox = document.getElementById("empty-state");
    errorBox.style.display = "block";
    errorBox.textContent = `No se pudo cargar el panel: ${err.message}`;
  }
}

init();
